def balanced_brackets(s):
    # Initialize a counter for unmatched brackets
    count = 0

    # Iterate through each character in the string
    for char in s:
        if char == '(' or char == '[' or char == '{':
            count += 1
        elif char == ')' or char == ']' or char == '}':
            count -= 1

        # If the counter goes negative, brackets are unmatched
        if count < 0:
            return False

    # If the counter is zero, all brackets are matched and nested
    return count == 0

