def count_islands(grid):
    if not grid or '0' in grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()

    def dfs(r, c):
        if (r, c) in visited or grid[r][c] == 0:
            return
        visited.add((r, c))
        for dr, dc in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            dfs(r + dr, c + dc)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                count += 1
                dfs(r, c)

    return count

