def eval_expression(s):
    stack = []
    operators = {'+': 1, '-': 1, '*': 2, '/': 2}

    for char in s:
        if char.isdigit():
            num = int(char)
            stack.append(num)
        elif char in operators:
            if len(stack) < 2:
                return -1
            num2 = stack.pop()
            num1 = stack.pop()
            if char == '+':
                result = num1 + num2
            elif char == '-':
                result = num1 - num2
            elif char == '*':
                result = num1 * num2
            else:
                result = int(num1 / num2)
            stack.append(result)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack[-1] != '(':
                num2 = stack.pop()
                num1 = stack.pop()
                result = eval_expression(f"{num1} {char} {num2}")
                stack.append(result)
            stack.pop()  # Remove the '('
    return int(stack[0]) if len(stack) == 1 else -1

