class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.lru_cache = {}

    def get(self, key):
        if key not in self.cache:
            return -1
        # Move the accessed item to the end of the list (LRU)
        self.lru_cache[key] = None
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            # Update the accessed item's value
            self.cache[key] = value
        else:
            if len(self.cache) == self.capacity:
                # Evict the least recently used item
                lru_key = next(iter(self.lru_cache))
                del self.cache[lru_key]
                del self.lru_cache[lru_key]

            # Add the new item to the end of the list (LRU)
            self.cache[key] = value
            self.lru_cache[key] = key

