def word_wrap(text, width):
    # Split the text into words and count the number of spaces
    word_count = len(text.split())

    # If width is less than or equal to 0, return an empty list
    if width <= 0:
        return []

    # If the number of spaces is greater than or equal to width, pack all words
    if word_count >= width:
        return [text]

    # Otherwise, pack the words into lines
    else:
        result = []
        for i in range(0, word_count, width):
            line = text[i:i+width]
            result.append(line)
        return result

def word_wrap(text, width):
    if width <= 0:
        raise ValueError("width must be greater than zero")

    lines = text.split()
    wrapped_lines = []

    for line in lines:
        if len(line) <= width:
            wrapped_lines.append(line)
        else:
            # If the current line is longer than the width, add a new line and wrap the rest
            wrapped_lines.append(line[:width])
            wrapped_lines.append(' '.join(line[width:]))

    return wrapped_lines

