def merge_k_sorted(lists):
    # Initialize a list to hold the result, starting with the first element of each inner list
    merged_list = [0] * len(lists[0])

    # Iterate over each list in the input
    for i, sublist in enumerate(lists):
        # Append elements from each sublist to the merged list
        for j, element in enumerate(sublist):
            if i == 0:
                merged_list[i] = element
            else:
                # If the current index is greater than 0, compare with the previous element
                if merged_list[i-1] < element:
                    merged_list[i] = element
                else:
                    # If the current index is not greater than 0, append to the end
                    merged_list.append(element)

    return merged_list

