from datetime import datetime, timedelta

def add_business_days(date_str, n):
    """
    Adds n business days to the given date.

    Parameters:
    - date_str (str): The date in 'YYYY-MM-DD' format.
    - n (int): The number of business days to add.

    Returns:
    - str: The date after n business days have been added, in 'YYYY-MM-DD' format.
    """
    # Convert the input string to a datetime object
    date_obj = datetime.strptime(date_str, "%Y-%m-%d")

    # Calculate the number of business days to add
    num_business_days = n % 7

    # If n is negative, adjust the number of business days
    if n < 0:
        num_business_days = -num_business_days

    # Add the business days to the date
    if num_business_days == 0:
        return date_obj.strftime("%Y-%m-%d")
    elif num_business_days == 1:
        return date_obj + timedelta(days=6)

    # Calculate the new day of the week
    if num_business_days == 2:
        return date_obj + timedelta(days=7)

    # Calculate the new weekday
    if num_business_days == 3:
        return date_obj + timedelta(days=2)

    # Calculate the new weekday
    if num_business_days == 4:
        return date_obj + timedelta(days=3)

    # Calculate the new weekday
    if num_business_days == 5:
        return date_obj + timedelta(days=4)

    # Calculate the new weekday
    if num_business_days == 6:
        return date_obj + timedelta(days=5)

    # Calculate the new weekday
    if num_business_days == 7:
        return date_obj + timedelta(days=6)

    # If the number of business days is greater than 7, add one more day
    return date_obj + timedelta(days=num_business_days)

