    sorted_unique_nums = sorted(set(nums))

    result = []
    current_range = ""

    for num in sorted_unique_nums:
        if not current_range or int(current_range[-1]) - int(num) > 1:
            current_range += str(num)
        else:
            result.append(current_range)
            current_range = str(num)

    # Add the last range if it's not empty
    result.append(current_range)

    return sorted(result)

