def group_consecutive_ranges(nums):
    if not nums:
        return []

    # Sort the numbers and remove duplicates
    sorted_unique_nums = list(set(nums))
    if len(sorted_unique_nums) < 2:
        return []

    # Group consecutive numbers
    grouped = {}
    current_group = []
    for num in sorted_unique_nums:
        if num - 1 in grouped:
            current_group.append(num)
        else:
            current_group.append(num)
            if len(current_group) == 2:
                grouped[current_group[-1]] = current_group[:-1]
        if len(current_group) > 2:
            grouped[current_group[-1]] = current_group[:-1]

    # Convert to strings and sort
    return sorted([''.join(group) for group in grouped.values()], key=lambda x: int(x.split('-')[0]))

