def group_consecutive_ranges(nums):
    # Sort the list to make it easier to handle duplicates and consecutive numbers
    nums.sort()

    # Initialize an empty list to store the result
    res = []

    # Iterate through the sorted list of numbers
    for i in range(len(nums)):
        if i == 0 or nums[i] != nums[i-1]:
            # If it's the first number or it's not consecutive, add it to the result
            if i == 0:
                res.append(str(nums[i]))
            else:
                # If it's consecutive, add the start and end of the range to the result
                res.append(str(nums[i-1]) + '-' + str(nums[i]))

    # Return the result, sorted in ascending order
    return sorted(res)

