def eval_expression(s):
    # Split the string into tokens based on spaces and operators
    tokens = s.split()

    def evaluate(tokens):
        if len(tokens) == 1:
            return int(tokens[0])

        # Evaluate the expression recursively
        result = evaluate(tokens[:-1])  # Remove the last token (space)
        if tokens[-1] == '+':
            return result + evaluate(tokens[1:])
        elif tokens[-1] == '-':
            return result - evaluate(tokens[1:])
        elif tokens[-1] == '*':
            return result * evaluate(tokens[1:])
        else:
            raise ValueError("Invalid operator")

    # Evaluate the entire expression
    return evaluate(tokens)

