def topo_sort(deps):
    # Initialize the graph and its in-degree for each task
    graph = {task: [] for task in deps}
    in_degree = {task: 0 for task in deps}

    # Build the graph and calculate in-degrees
    for task, prerequisites in deps.items():
        for prerequisite in prerequisites:
            graph[prerequisite].append(task)
            in_degree[task] += 1

    # Initialize the result list and visited set
    result = []
    visited = {task for task in deps}

    # Perform topological sort
    while len(visited) > 0:
        current_task = None
        for task in sorted(visited, key=lambda x: -in_degree[x]):
            if current_task is None or in_degree[current_task] == 0:
                current_task = task
            else:
                visited.remove(current_task)
        if current_task is not None:
            result.append(current_task)

    return result

