    start, end = 0, 0

    for i in range(len(nums)):
        if i == 0 or nums[i] != nums[i-1]:
            # If it's the first run, start a new group
            if end == 0:
                result.append(str(nums[i]))
            else:
                # Otherwise, add the end of the current group to the result
                result.append(f"{end - start + 1}-{nums[i-1]}")
            end = i

    # Add the last group if it's not empty
    if end:
        result.append(f"{end - start + 1}-{nums[-1]}")

    # Sort the result list
    return sorted(result)
