def roman_to_int(s):
    # Mapping of Roman numerals to their integer values
    rom_val = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
               'C': 100, 'D': 500, 'M': 1000}
    # Reverse mapping for easy lookup
    val_rom = {v: k for k, v in rom_val.items()}

    # Initialize the integer value
    total = 0

    # Iterate through the string, excluding spaces
    for i in range(len(s) - 1):
        # Check if the current and next character form a subtractive pair
        if s[i:i+2] in val_rom:
            # Add the value of the subtractive pair
            total += rom_val[s[i:i+2]]
        else:
            # Add the value of a single character
            total += rom_val[s[i]]

    # Handle the last character if it's a subtractive pair
    if s[-2:] in val_rom:
        total += rom_val[s[-2:]]

    return total

