    return transposed

def count_islands(grid):
    """
    Counts the number of connected 1s in a 2D grid where cells connect ORTHOGONALLY.
    """
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()

    def dfs(r, c):
        if (
            r < 0 or
            r >= rows or
            c < 0 or
            c >= cols or
            (r, c) in visited or
            grid[r][c] == 0
        ):
            return

        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            dfs(r + dr, c + dc)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if (r, c) not in visited and grid[r][c] == 1:
                dfs(r, c)
                count += 1
    return count

