    counts = {}
    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Filter out numbers that appear only once
    duplicates = [num for num, count in counts.items() if count > 1]

    # Return the sorted list of duplicates
    return sorted(duplicates)

