    def calculate(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                else:
                    if a < 0 and b > 0 or a > 0 and b < 0:
                        stack.append(-((a // b) + (1 if a % b != 0 else 0)))
