def wildcard_match(s, p):
    """
    Checks if the string s matches the pattern p.

    Parameters:
        s (str): The input string to match against the pattern.
        p (str): The pattern string which may contain '*' and '?' characters.

    Returns:
        bool: True if s matches the pattern p, False otherwise.
    """
    def match(i, j):
        # Base case: if both indices are out of bounds
        if i == len(s) and j == len(p):
            return True
        # Base case: if pattern index is out of bounds but string is not
        elif j == len(p):
            return False

        # Match current characters or '*' to skip a character
        if j + 1 < len(p) and p[j+1] == '*':
            return match(i, j+2) or (i < len(s) and (s[i] == p[j] or p[j] == '?') and match(i+1, j))

        # Match current characters or '?' to skip a character
        if i < len(s) and (s[i] == p[j] or p[j] == '?'):
            return match(i+1, j+1)

        # Characters do not match
        return False

    return match(0, 0)

