def wildcard_match(s, p):
    """
    Checks if the string s matches the pattern p.

    The '*' character in p can match any sequence of characters including the empty sequence, and '?' matches exactly one character.
    """
    # Initialize DP table
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True  # Empty string matches empty pattern

    for i in range(1, len(p) + 1):
        if p[i - 1] == '*':
            dp[0][i] = dp[0][i - 1]

    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or (dp[i - 1][j] and (s[i - 1] == p[j - 2] or p[j - 2] == '?'))
            else:
                dp[i][j] = (dp[i - 1][j - 1] and s[i - 1] == p[j - 1])

    return dp[len(s)][len(p)]

