def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by the start of each interval
    sorted_intervals = sorted(intervals)

    merged = []
    for current in sorted_intervals:
        # If the list of merged intervals is empty or if the current interval does not overlap with the previous, simply append it.
        if not merged or merged[-1][0] > current[0]:
            merged.append(current)
        else:
            # Otherwise, there is an overlap. We merge the current interval with the last in the merged list.
            merged[-1][0] = min(merged[-1][0], current[0])
            merged[-1][1] = max(merged[-1][1], current[1])

    return merged

