def camel_to_snake(s):
    # Split the string into words based on capital letters and consecutive capitals forming an acronym
    parts = []
    i = 0

    while i < len(s):
        if s[i].isupper() and (i == 0 or not s[i-1].islower()):
            if i > 0 and s[i-1] == '_':
                parts.append(s[i].lower())
            else:
                parts.append('_' + s[i].lower())
        elif i > 0 and not s[i-1].isupper():
            parts.append(s[i].lower())
        i += 1

    return ''.join(parts)

