def eval_expression(s):
    def evaluate(expression):
        stack = []
        for char in expression:
            if char.isdigit():
                num = 0
                while char.isdigit() or (char == '-' and stack[-1].isdigit()):
                    num = num * 10 + int(char)
                    char = stack.pop()
                stack.append(num)
            elif char in "+-*/":
                if len(stack) < 2:
                    return None
                operator = char
                right = stack.pop()
                left = stack.pop()
                if operator == '+':
                    result = left + right
                elif operator == '-':
                    result = left - right
                elif operator == '*':
                    result = left * right
                else:
                    if left < 0 and right > 0 or (left > 0 and right < 0):
                        result = -(-left // right)
                    else:
                        result = left // right
                stack.append(result)
        return stack[0]

    def parse_expression(expression):
        i = 0
        while i < len(expression) and expression[i] == ' ':
            i += 1
        if i >= len(expression):
            return expression
        start = i
        while i < len(expression) and (expression[i].isdigit() or expression[i] in "+-*/"):
            i += 1
        end = i - 1
        return expression[start:end]

    while "()" in s:
        s = s.replace("()", "")
    return evaluate(parse_expression(s))

