def eval_expression(s: str) -> int:
    def calculate(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                else:
                    if a < 0 and b > 0 or a > 0 and b < 0:
                        stack.append(-((a // b) + (1 if a % b != 0 else 0)))
                    else:
                        stack.append(a // b)
        return stack[0]

    tokens = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            i += 1
        elif s[i].isdigit():
            j = i + 1
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j
        elif s[i] == '(':
            tokens.append('(')
            i += 1
        elif s[i].isdigit():
            j = i + 1
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j + 1
        elif s[i] == ')':
            tokens.append(')')
            i += 1

    return calculate(tokens)
