def topo_sort(deps: Dict[str, List[str]]) -> List[str]:
    def dfs(task):
        if task in visited:
            return False
        if not graph[task]:
            return True
        visited.add(task)
        for prereq in deps[task]:
            if not dfs(prereq):
                return False
        visited.remove(task)
        graph[task] = []
        order.append(task)
        return True

    visited = set()
    graph = {task: [] for task in deps}
    order = []

    # Check for cycles
    for task in deps:
        if not dfs(task):
            return None

    # Reconstruct the order
    for task in sorted(deps.keys()):
        if not graph[task]:
            return [order.pop()] + topo_sort(deps)

    return []

