def wildcard_match(s, p):
    """
    Check if the whole string s matches the pattern p.

    :param s: The target string to match.
    :type s: str
    :param p: The pattern string, which may contain '*' and '?' characters.
    :type p: str
    :return: True if s matches the pattern, False otherwise.
    :rtype: bool
    """

    def match(i, j):
        if i == len(s) and j == len(p):
            return True
        elif i < len(s) and (j == len(p) or p[j] != '*'):
            return False
        elif j < len(p) and (p[j] == '?' or p[j] == s[i]):
            return match(i + 1, j + 1)
        elif p[j] == '*':
            return match(i, j + 1) or (i < len(s) and match(i + 1, j))
        else:
            return False

    return match(0, 0)

