    # Split version strings into components and pad with zeros if necessary
    a_parts = [int(part) for part in a.split('.')]
    b_parts = [int(part) for part in b.split('.')]

    # Compare components from left to right
    for i, (a_part, b_part) in enumerate(zip(a_parts, b_parts)):
        if a_part != b_part:
            return 1 if a_part > b_part else -1

    # If all components are equal, return 0
    return 0

