def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by the start of each interval
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged_list = [sorted_intervals[0]]

    for current_interval in sorted_intervals[1:]:
        last_merged = merged_list[-1]

        # If the current interval starts after the end of the last merged interval, add it
        if current_interval[0] > last_merged[1]:
            merged_list.append(current_interval)
        else:
            # Merge the intervals if they overlap
            last_merged[1] = max(last_merged[1], current_interval[1])

    return merged_list

