def max_subarray_sum(nums):
    if not nums:
        return 0

    current_max = global_max = nums[0]

    for num in nums:
        if current_max + num > num:
            current_max += num
        else:
            current_max = num

        if current_max > global_max:
            global_max = current_max

    return global_max
```

