def min_coins(coins, amount):
    """
    Returns the fewest coins summing exactly to amount or -1 if impossible.

    :param coins: List of coin denominations
    :type coins: list[int]
    :param amount: Target sum in cents
    :type amount: int
    :return: Fewest number of coins needed to sum exactly to amount or -1 if impossible
    :rtype: int
    """

    def dp(amount, coins):
        # Base case: if amount is 0 or negative
        if amount < 0:
            return float('inf')

        # If the result is already computed, return it
        if amount in memo:
            return memo[amount]

        # Initialize the minimum coins needed
        min_coins = float('inf')

        # Try each coin denomination
        for coin in coins:
            if amount >= coin:
                min_coins = min(min_coins, 1 + dp(amount - coin, coins))

        # Store the computed result in memo
        memo[amount] = min_coins

        return min_coins

    # Memoization dictionary
    memo = {}

    # Compute the minimum coins needed for each amount up to 'amount'
    return dp(amount, coins)

