def rotate_list(lst, k):
    if not lst:
        return []

    n = len(lst)
    k %= n  # Normalize k to avoid unnecessary rotations

    if k == 0:
        return lst.copy()

    # Perform rotation
    rotated_lst = [lst[(i + k) % n] for i in range(n)]

    return rotated_lst
```

