def eval_expression(s):
    def apply_operator(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        else:  # division
            return int(a / b)

    def parse_expression(expression):
        stack = []
        i = 0
        while i < len(expression):
            if expression[i] == ' ':
                i += 1
                continue
            elif expression[i].isdigit():
                num = ''
                while i < len(expression) and expression[i].isdigit():
                    num += expression[i]
                    i += 1
                stack.append(int(num))
            elif expression[i] in '+-*/':
                while len(stack) > 1 and (stack[-2] >= '0' and stack[-2] <= '9') or (
                        (stack[-1] == '(') and (stack[-2] in '+-*/')):
                    yield apply_operator(stack.pop(), stack.pop(), stack.pop())
                stack.append(expression[i])
            elif expression[i] == '(':
                stack.append('(')
                i += 1
            elif expression[i] == ')':
                while stack and stack[-1] != '(':
                    yield apply_operator(stack.pop(), stack.pop(), stack.pop())
                if not stack or stack[-1] != '(':
                    raise ValueError("Mismatched parentheses")
                del stack[-1]
                i += 1
        while len(stack) > 1:
            yield apply_operator(stack.pop(), stack.pop(), stack.pop())
        if len(stack) == 1:
            return stack[0]

    return parse_expression(s)
