import re

def eval_expression(s):
    def parse_number(match):
        return int(match.group(0))

    def precedence(op):
        if op in "+-":
            return 1
        elif op == "*":
            return 2
        else:
            return 3

    def apply_operation(a, b, op):
        if op == "+":
            return a + b
        elif op == "-":
            return a - b
        elif op == "*":
            return a * b
        else:
            # Integer division truncates toward zero
            if op == "/":
                return a // b

    def evaluate(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token == "(":
                stack.append(evaluate(tokens))
            else:
                right = stack.pop()
                left = stack.pop()
                op = token
                result = apply_operation(left, right, op)
                stack.append(result)

        return stack[0]

    tokens = re.findall(r'\d+|\(|\)|[\+\-\*/]', s)
    return evaluate(tokens)

