    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.usage_map = {}

    def get(self, key: int) -> int:
        if key in self.cache and key not in self.usage_map:
            self.usage_map[key] = 1
        elif key in self.cache and key in self.usage_map:
            del self.usage_map[key]
            self.usage_map[key] = 1
        elif key not in self.cache:
            return -1

        if len(self.usage_map) > self.capacity:
            min_key = next(iter(self.usage_map))
            del self.cache[min_key]
            del self.usage_map[min_key]

        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache and key not in self.usage_map:
            del self.cache[key]
            del self.usage_map[key]

        if key in self.cache or len(self.cache) >= self.capacity:
            del self.usage_map[key]
        else:
            self.usage_map.pop(key, None)

