from typing import *
from collections import defaultdict, deque


def topo_sort(deps: Dict[str, List[str]]) -> Optional[List[str]]:
    if not deps:
        return []

    # Initialize the graph and indegree array
    graph = defaultdict(list)
    in_degree = {task: 0 for task in deps}
    for task, prerequisites in deps.items():
        for prerequisite in prerequisites:
            graph[prerequisite].append(task)
            in_degree[task] += 1

    # Initialize the queue with tasks that have no prerequisites
    queue = deque([task for task in in_degree if in_degree[task] == 0])

    # Perform topological sorting
    sorted_tasks = []
    while queue:
        task = queue.popleft()
        sorted_tasks.append(task)
        for successor in graph[task]:
            in_degree[successor] -= 1
            if in_degree[successor] == 0:
                queue.append(successor)

    # Check for cycles
    if len(sorted_tasks) != len(deps):
        return None

    # Return the sorted tasks
    return sorted_tasks

