def topo_sort(deps):
    from collections import deque

    # Initialize the graph and indegree dictionary
    graph = {}
    indegree = {}

    for task, prerequisites in deps.items():
        if task not in graph:
            graph[task] = []
        for prerequisite in prerequisites:
            if prerequisite not in indegree:
                indegree[prerequisite] = []
            indegree[prerequisite].append(task)

    # Initialize the queue with tasks without prerequisites
    queue = deque([task for task in deps if not indegree.get(task, [])])

    # Initialize the result list
    result = []

    while queue:
        task = queue.popleft()
        if task not in graph:
            continue
        for neighbor in graph[task]:
            indegree[neighbor].remove(task)
            if not indegree[neighbor]:
                queue.append(neighbor)
        result.append(task)

    # If the graph has cycles, return None
    if any(len(indegree[task]) > 0 for task in graph):
        return None

    # Reverse the result to get a valid order
    return list(reversed(result))
