def topo_sort(deps):
    from collections import deque

    def dfs(task, visited, stack):
        if task in visited:
            return
        visited.add(task)
        for prereq in deps[task]:
            dfs(prereq, visited, stack)
        stack.appendleft(task)

    tasks = list(deps.keys())
    visited = set()
    stack = deque()

    for task in tasks:
        dfs(task, visited, stack)

    if len(stack) != len(tasks):
        return None
    else:
        return list(stack)
