def next_permutation(nums):
    n = len(nums)

    # Find the first element from the right that is smaller than its next element
    for i in range(n - 2, -1, -1):
        if nums[i] < nums[i + 1]:
            break
    else:
        # If no such element is found, the list is in descending order
        return nums[::-1]

    # Find the smallest element to the right of i that is larger than nums[i]
    for j in range(n - 1, i, -1):
        if nums[j] > nums[i]:
            break

    # Swap the found elements
    nums[i], nums[j] = nums[j], nums[i]

    # Reverse the elements from i+1 to the end of the list
    nums[i + 1:] = reversed(nums[i + 1:])

    return nums
```

